from pptx import Presentation
from pptx.util import Emu
prs = Presentation('copaw_gateway_dashboard.pptx')
for i, slide in enumerate(prs.slides, 1):
    print(f"\n=== Slide {i} ===")
    for shape in slide.shapes:
        if shape.has_chart:
            ch = shape.chart
            print(f"  CHART type={ch.chart_type}")
            cats = list(ch.plots[0].categories)
            print(f"    categories={cats}")
            for ser in ch.plots[0].series:
                print(f"    series '{ser.name}': {[round(v,2) for v in ser.values]}")
        elif getattr(shape, "has_text_frame", False) and shape.has_text_frame and shape.text_frame.text.strip():
            print(f"  TEXT: {shape.text_frame.text[:80]!r}")

